def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    # If no opponents are alive, conserve budget.
    if not alive_opponents:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.35))

    # Read yesterday bids from previous_trace only.
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Baseline based on supply: with lower supply, bidding should be higher.
    # supply in [15,25], so normalize.
    if supply <= MIN_SUPPLY:
        supply_pressure = 1.0
    elif supply >= MAX_SUPPLY:
        supply_pressure = 0.6
    else:
        supply_pressure = 1.0 - 0.4 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # Determine opponent pressure from yesterday.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / max(1, len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # If someone previously bid extremely high, others likely chase; but match only partially.
    extreme_threshold = DAILY_SALARY * 1.5  # 105

    # HP urgency.
    if my_hp <= 2.0:
        hp_factor = 1.0
    elif my_hp <= 4.0:
        hp_factor = 0.8
    else:
        hp_factor = 0.55

    # If we've already had no water days, increase urgency.
    if my_no_water_days >= 2:
        hp_factor = min(1.0, hp_factor + 0.15)

    # Core bid target.
    # - If highest bid was extreme, bid around a fraction of that to stay competitive.
    # - Otherwise, bid around a fraction of average/highest.
    if highest_prev_bid >= extreme_threshold:
        target = min(highest_prev_bid * 0.45, avg_prev_bid * 0.75 + 10.0)
    else:
        target = max(DAILY_SALARY * 0.45, avg_prev_bid * 0.55)

    # Apply supply pressure and HP factor.
    target = target * supply_pressure * (0.75 + 0.25 * hp_factor)

    # Ensure we don't overspend; also keep a minimum bid to avoid being shut out.
    # If we are low on budget, cap aggressively.
    max_affordable = max(0.0, my_budget)

    # Minimum bid depends on urgency.
    min_bid = 0.0
    if my_hp <= 2.0:
        min_bid = DAILY_SALARY * 0.75
    elif my_hp <= 4.0:
        min_bid = DAILY_SALARY * 0.6
    else:
        min_bid = DAILY_SALARY * 0.45

    bid = max(min_bid, target)
    bid = min(bid, max_affordable)

    # Final safety: if budget is tiny, spend what we can.
    if bid <= 0.0 and my_budget > 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, DAILY_SALARY * 0.75)
        return min(budget, DAILY_SALARY * 0.35)

    total_players = 1 + len(alive)
    market_ratio = supply / float(total_players * WATER_REQ)

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water_days >= 2:
        target = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif no_water_days >= 1 or hp <= 4:
        target = max(DAILY_SALARY * 0.82, highest_prev + 2.0)
    else:
        if market_ratio >= 0.28:
            target = max(DAILY_SALARY * 0.42, avg_prev * 0.72)
        elif market_ratio >= 0.22:
            target = max(DAILY_SALARY * 0.62, avg_prev * 0.92, highest_prev + 1.5)
        else:
            target = max(DAILY_SALARY * 0.8, highest_prev + 2.5)

    if urgent_opp >= 2:
        target += 4.0
    elif urgent_opp == 0 and market_ratio >= 0.25:
        target -= 5.0

    if rich_opp >= 2 and market_ratio < 0.24:
        target += 3.0

    if day >= 8 and hp >= 6 and no_water_days == 0 and market_ratio >= 0.25:
        target *= 0.9

    cap = budget
    if hp >= 6 and no_water_days == 0:
        reserve = DAILY_SALARY * max(0, 10 - day) * 0.18
        cap = max(0.0, budget - reserve)
        if cap <= 0:
            cap = min(budget, DAILY_SALARY * 0.55)

    bid = min(cap, target)
    if hp <= 3 or no_water_days >= 1:
        bid = min(budget, max(bid, DAILY_SALARY * 0.78))

    if bid < 0:
        bid = 0
    return float(min(budget, bid))

