            bid_value = max(bid_value, DAILY_SALARY * 1.1)
        elif my_hp > 2:
            bid_value = max(bid_value, DAILY_SALARY * 1.2)

    final_bid = min(bid_value, my_budget)

    final_bid = max(final_bid, 1.0) if my_budget > 0 else 0.0

